UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Un mutuo di 150.000&euro; a 25 anni con tasso fisso al 3,5% ha una rata mensile di circa 751&euro;. Nella <strong>prima rata</strong>, circa 438&euro; sono interessi e solo 313&euro; riducono il capitale. Nell''<strong>ultima rata</strong>, la proporzione si ribalta quasi completamente: pochi euro di interessi, quasi tutto capitale. Ecco perché negli anni iniziali il debito residuo scende così lentamente rispetto a quanto ci si aspetterebbe guardando solo l''importo pagato.</p>',
