y-2.5">121ª</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">306</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">445</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">104.599</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">181ª</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">221</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">529</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">75.410</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">241ª</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">120</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">631</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">40.648</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">300ª</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">2</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">749</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">0</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Mutuo da 150.000 euro a 25 anni, tasso fisso 3,5%, rata costante di 750,94 euro. Le rate indicate sono la prima del 1°, 6°, 11°, 16° e 21° anno, e l''ultima.</p></figure><figure class="my-6 rounded-xl border border-border bg-white p-5"><figcaption class="mb-4 text-sm font-semibold text-gray-900">Interessi pagati ogni 5 anni</figcaption><div class="space-y-3"><div><div class="mb-1 flex justify-between gap-3 text-sm"><span class="text-gray-700">Anni 1-5</span><span class="whitespace-nowrap font-mono text-gray-900">24.537 €</span></div><div class="h-2.5 rounded-full bg-gray-100"><div class="h-2.5 roun