UPDATE news_articles SET body = REPLACE(body,
    '<ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Durata residua</strong> — un mutuo breve (10 anni) espone meno all''incertezza di lungo periodo rispetto a uno da 30 anni.</li><li><strong>Margine di bilancio</strong> — se un aumento di rata del 20-30% metterebbe in difficoltà il bilancio familiare, la certezza del fisso vale probabilmente il premio pagato.</li><li><strong>Fase del ciclo dei tassi</strong> — il divario tra fisso e variabile si allarga o si stringe in base alle aspettative di mercato sui tassi futuri, che cambiano nel tempo.</li></ul>',
    '<ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Durata residua</strong> — un mutuo breve (10 anni) espone meno all''incertezza di lungo periodo rispetto a uno da 30 anni.</li><li><strong>Margine di bilancio</strong> — se un aumento di rata del 20-30% metterebbe in difficoltà il bilancio familiare, la certezza del fisso vale probabilmente il premio pagato.</li><li><strong>Fase del ciclo dei tassi</strong> — il divario tra fisso e variabile si allarga o si stringe in base alle aspettative di mercato sui tassi futuri, che cambiano nel tempo.</li></ul><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Fisso o variabile: tre scenari a confronto (importi in euro)</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Scenario</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Rata iniziale</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Rata dal 4° anno</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Interessi totali</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Fisso 3,3%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">735</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">735</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">70.483</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Variabile, tassi stabili</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">673</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">673</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">51.878</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Variabile, +1,5 punti dal 4° anno</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">673</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">779</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">79.756</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Variabile, −0,5 punti dal 4° anno</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">673</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">640</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">43.112</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Mutuo da 150.000 euro a 25 anni. Tassi di esempio: fisso 3,3%, variabile in partenza 2,5%. Nel variabile la rata si ricalcola sul debito residuo quando cambia il tasso.</p></figure>'),
