UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Più l''LTV è alto, più basso è il margine di sicurezza della banca se in futuro dovesse rientrare del credito rivendendo l''immobile (ad esempio in caso di insolvenza prolungata): con un LTV al 90%, basta un calo del valore dell''immobile del 10-15% perché il valore di garanzia scenda sotto il debito residuo. Con un LTV al 60%, lo stesso calo lascia comunque un margine consistente.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Più l''LTV è alto, più basso è il margine di sicurezza della banca se in futuro dovesse rientrare del credito rivendendo l''immobile (ad esempio in caso di insolvenza prolungata): con un LTV al 90%, basta un calo del valore dell''immobile del 10-15% perché il valore di garanzia scenda sotto il debito residuo. Con un LTV al 60%, lo stesso calo lascia comunque un margine consistente.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Immobile da 200.000 euro: LTV, anticipo e margine della banca (importi in euro)</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">LTV</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Mutuo</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Anticipo</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Margine se il valore cala del 15%</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">60%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">120.000</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">80.000</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">50.000</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">80%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">160.000</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">40.000</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">10.000</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">90%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">180.000</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">20.000</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">−10.000</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">100%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">200.000</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">0</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">−30.000</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Margine: valore dell''immobile dopo un calo del 15% (170.000 euro) meno il mutuo. Un margine negativo vuol dire che la casa vale meno del debito. Per semplicità il debito è quello iniziale.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'loan-to-value-ltv-mutuo-quanto-puoi-finanziare' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Se l''acquisto passa da un''agenzia immobiliare, la provvigione (di solito una percentuale del prezzo, spesso dovuta sia da chi compra che da chi vende) va sommata a tutto il resto — e va contrattata prima, non dopo aver già trovato la casa giusta.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Se l''acquisto passa da un''agenzia immobiliare, la provvigione (di solito una percentuale del prezzo, spesso dovuta sia da chi compra che da chi vende) va sommata a tutto il resto — e va contrattata prima, non dopo aver già trovato la casa giusta.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Le spese accessorie in sintesi</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Voce</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Da cosa dipende</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Notaio (compravendita e mutuo)</td><td class="px-3 py-2 sm:px-4 sm:py-2.5">Valore dell''immobile e notaio scelto: onorari negoziabili</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Imposte di registro, ipotecaria e catastale</td><td class="px-3 py-2 sm:px-4 sm:py-2.5">Prima o seconda casa, acquisto da privato o da impresa (IVA)</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Imposta sostitutiva sul mutuo</td><td class="px-3 py-2 sm:px-4 sm:py-2.5">Importo finanziato, aliquota agevolata per la prima casa</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Perizia e istruttoria</td><td class="px-3 py-2 sm:px-4 sm:py-2.5">Banca: costo fisso o in percentuale, a volte azzerato in promozione</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Agenzia immobiliare</td><td class="px-3 py-2 sm:px-4 sm:py-2.5">Percentuale sul prezzo, da contrattare prima</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Chiedi un preventivo scritto al notaio e il dettaglio delle spese alla banca prima di firmare il preliminare.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'spese-notarili-accessorie-mutuo-costo-reale-acquisto-casa' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Un punto spesso frainteso: la garanzia riduce l''anticipo richiesto e facilita l''accesso al credito, ma il mutuo va restituito per intero come qualunque altro — cambia chi si fa garante di una parte del rischio verso la banca, non l''importo che il richiedente deve rimborsare nel tempo.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Un punto spesso frainteso: la garanzia riduce l''anticipo richiesto e facilita l''accesso al credito, ma il mutuo va restituito per intero come qualunque altro — cambia chi si fa garante di una parte del rischio verso la banca, non l''importo che il richiedente deve rimborsare nel tempo.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Casa da 200.000 euro: con e senza garanzia (importi in euro)</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5"></th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Anticipo</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Rata mensile</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Interessi totali</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Senza garanzia (mutuo all''80%)</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">40.000</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">675</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">82.844</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Con garanzia (mutuo al 100%)</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">0</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">843</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">103.555</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Esempio a 30 anni con tasso fisso del 3%, spese accessorie escluse (restano comunque da pagare). Meno anticipo vuol dire più debito: rata e interessi salgono.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'mutuo-giovani-under-36-garanzia-prima-casa' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il risparmio sugli interessi da un''estinzione anticipata equivale, in pratica, a un rendimento <strong>certo e senza rischio</strong> pari al tasso del tuo mutuo. Se il tuo mutuo ha un tasso fisso al 2%, e potresti investire quella stessa somma in uno strumento diversificato con un rendimento atteso storico del 6-7% annuo (seppur non garantito), matematicamente potrebbe convenirti di più investire piuttosto che estinguere. Se invece il tuo mutuo ha un tasso al 4-5%, il confronto si stringe molto, e la certezza del risparmio sugli interessi comincia a pesare di più.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il risparmio sugli interessi da un''estinzione anticipata equivale, in pratica, a un rendimento <strong>certo e senza rischio</strong> pari al tasso del tuo mutuo. Se il tuo mutuo ha un tasso fisso al 2%, e potresti investire quella stessa somma in uno strumento diversificato con un rendimento atteso storico del 6-7% annuo (seppur non garantito), matematicamente potrebbe convenirti di più investire piuttosto che estinguere. Se invece il tuo mutuo ha un tasso al 4-5%, il confronto si stringe molto, e la certezza del risparmio sugli interessi comincia a pesare di più.</p><figure class="my-6 rounded-xl border border-border bg-white p-5"><figcaption class="mb-4 text-sm font-semibold text-gray-900">Cosa rendono 10.000 euro in 10 anni</figcaption><div class="space-y-3"><div><div class="mb-1 flex justify-between gap-3 text-sm"><span class="text-gray-700">Estinguere un mutuo al 2%</span><span class="whitespace-nowrap font-mono text-gray-900">2.190 €</span></div><div class="h-2.5 rounded-full bg-gray-100"><div class="h-2.5 rounded-full bg-income" style="width:34.8%"></div></div></div><div><div class="mb-1 flex justify-between gap-3 text-sm"><span class="text-gray-700">Estinguere un mutuo al 3,5%</span><span class="whitespace-nowrap font-mono text-gray-900">4.106 €</span></div><div class="h-2.5 rounded-full bg-gray-100"><div class="h-2.5 rounded-full bg-income" style="width:65.3%"></div></div></div><div><div class="mb-1 flex justify-between gap-3 text-sm"><span class="text-gray-700">Estinguere un mutuo al 5%</span><span class="whitespace-nowrap font-mono text-gray-900">6.289 €</span></div><div class="h-2.5 rounded-full bg-gray-100"><div class="h-2.5 rounded-full bg-income" style="width:100.0%"></div></div></div><div><div class="mb-1 flex justify-between gap-3 text-sm"><span class="text-gray-700">Investire al 6% annuo (non garantito)</span><span class="whitespace-nowrap font-mono text-gray-900">5.852 €</span></div><div class="h-2.5 rounded-full bg-gray-100"><div class="h-2.5 rounded-full bg-accent" style="width:93.1%"></div></div></div></div><p class="mt-4 text-xs text-muted">Approssimazione: il risparmio di interessi cresce come un capitale investito al tasso del mutuo. Investimento: rendimento atteso del 6% annuo, con il 26% di tasse sul guadagno. Detrazione fiscale esclusa.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'estinzione-anticipata-mutuo-quando-conviene' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Conviene valutarla seriamente quando il divario tra il tuo tasso attuale e le condizioni di mercato è consistente e hai ancora diversi anni di durata residua davanti — più tempo resta, più anni di risparmio sugli interessi puoi ottenere dal cambio. Vale anche la pena calcolare l''impatto sul piano di ammortamento, visto che <a href="/news/ammortamento-alla-francese-guida-mutuo-rata-costante" class="text-accent hover:underline font-medium">nei primi anni la quota interessi pesa di più</a> sulla rata.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Conviene valutarla seriamente quando il divario tra il tuo tasso attuale e le condizioni di mercato è consistente e hai ancora diversi anni di durata residua davanti — più tempo resta, più anni di risparmio sugli interessi puoi ottenere dal cambio. Vale anche la pena calcolare l''impatto sul piano di ammortamento, visto che <a href="/news/ammortamento-alla-francese-guida-mutuo-rata-costante" class="text-accent hover:underline font-medium">nei primi anni la quota interessi pesa di più</a> sulla rata.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Esempio di surroga: 120.000 euro di debito residuo, 20 anni rimasti</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5"></th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Tasso 4% (attuale)</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Tasso 3% (surroga)</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Rata mensile</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">727,18 €</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">665,52 €</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Interessi ancora da pagare</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">54.522 €</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">39.724 €</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5 font-semibold text-gray-900">Risparmio con la surroga</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono font-semibold text-gray-900">—</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono font-semibold text-gray-900">14.798 €</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Stessa durata residua. La surroga per legge non costa nulla a chi la chiede.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'surroga-mutuo-cosa-e-come-funziona' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Per <strong>confrontare offerte diverse</strong> il numero giusto è il TAEG: un mutuo con TAN più basso ma spese alte può avere un TAEG più alto di un concorrente con TAN leggermente superiore e spese azzerate. Il TAN resta utile per un''altra domanda, cioè quanto pagherai di rata ogni mese.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Per <strong>confrontare offerte diverse</strong> il numero giusto è il TAEG: un mutuo con TAN più basso ma spese alte può avere un TAEG più alto di un concorrente con TAN leggermente superiore e spese azzerate. Il TAN resta utile per un''altra domanda, cioè quanto pagherai di rata ogni mese.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Due offerte per 150.000 euro a 25 anni (importi in euro)</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5"></th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">TAN</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Spese</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">TAEG</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Offerta A</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">3,00%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5">3.000 + 3,00 a rata</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">3,27%</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Offerta B</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">3,10%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5">300</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">3,16%</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Spese: istruttoria e perizia, più l''eventuale costo di incasso di ogni rata. L''offerta A ha il TAN più basso ma costa di più: il TAEG lo mostra.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'tan-e-taeg-mutuo-differenza' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">È l''indice di riferimento dei <strong>mutui a tasso variabile</strong>: il tuo tasso è Euribor più spread, e si aggiorna periodicamente seguendo l''andamento dell''indice. L''Euribor si muove soprattutto in base alle decisioni della Banca Centrale Europea sui tassi ufficiali: quando la BCE alza i tassi, l''Euribor sale e con lui la rata del variabile.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">È l''indice di riferimento dei <strong>mutui a tasso variabile</strong>: il tuo tasso è Euribor più spread, e si aggiorna periodicamente seguendo l''andamento dell''indice. L''Euribor si muove soprattutto in base alle decisioni della Banca Centrale Europea sui tassi ufficiali: quando la BCE alza i tassi, l''Euribor sale e con lui la rata del variabile.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Mutuo variabile: rata al variare dell''Euribor (importi in euro)</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Euribor</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Tasso (spread 1%)</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Rata</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">In più al mese</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">1,0%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">2,0%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">635,78</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">—</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">2,0%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">3,0%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">711,32</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">+76</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">3,0%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">4,0%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">791,76</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">+156</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">4,0%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">5,0%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">876,89</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">+241</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Mutuo da 150.000 euro a 25 anni, rata calcolata come se il tasso restasse quello per tutta la durata.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'euribor-irs-mutuo-cosa-sono' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">La detrazione è pari al <strong>19% degli interessi passivi</strong> pagati nell''anno, e degli oneri accessori, calcolata su un importo massimo di <strong>4.000 euro</strong>. Il beneficio massimo è quindi di 760 euro all''anno, che riducono l''IRPEF dovuta e si traducono di solito in un rimborso in busta paga o con la pensione.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">La detrazione è pari al <strong>19% degli interessi passivi</strong> pagati nell''anno, e degli oneri accessori, calcolata su un importo massimo di <strong>4.000 euro</strong>. Il beneficio massimo è quindi di 760 euro all''anno, che riducono l''IRPEF dovuta e si traducono di solito in un rimborso in busta paga o con la pensione.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Quanto si recupera anno per anno (importi in euro)</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Anno</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Interessi pagati</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Detraibili (max 4.000)</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Detrazione (19%)</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">1° anno</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">5.189</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">4.000</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">760</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">5° anno</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">4.616</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">4.000</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">760</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">10° anno</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">3.776</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">3.776</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">717</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">15° anno</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">2.777</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">2.777</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">528</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">20° anno</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">1.586</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">1.586</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">301</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">25° anno</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">169</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">169</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">32</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Mutuo da 150.000 euro a 25 anni al 3,5%. Nei primi anni gli interessi superano il tetto di 4.000 euro: la parte in eccesso non si detrae.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'detrazione-interessi-mutuo-prima-casa' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Allungare la durata aumenta l''importo ottenibile, ma anche il totale degli interessi pagati: lo vedi bene nel piano di <a href="/news/ammortamento-alla-francese-guida-mutuo-rata-costante" class="text-accent hover:underline font-medium">ammortamento</a>.</p>',
